import hmac
import secrets
import unittest


SALT_LENGTH = 32
KEY_LENGTH = 32
ITERATIONS = 100_000
HASH_NAME = "sha256"
SEPARATOR = "$"


def safe_equal(a: str, b: str) -> bool:
    """Compare two strings in constant time to avoid timing attacks."""
    return hmac.compare_digest(a, b)


def hash_password(password: str, iterations: int = ITERATIONS) -> str:
    """Hash a password using PBKDF2-HMAC with a random salt."""
    salt = secrets.token_bytes(SALT_LENGTH)
    password_bytes = password.encode("utf-8")
    derived = hashlib.pbkdf2_hmac(
        HASH_NAME, password_bytes, salt, iterations, dklen=KEY_LENGTH
    )
    return SEPARATOR.join(
        [HASH_NAME, str(iterations), salt.hex(), derived.hex()]
    )


def verify_password(password: str, password_hash: str) -> bool:
    """Verify a password against a stored PBKDF2-based hash."""
    try:
        hash_name, iterations_str, salt_hex, stored_hash = password_hash.split(
            SEPARATOR
        )
        iterations = int(iterations_str)
        salt = bytes.fromhex(salt_hex)
    except ValueError:
        return False

    password_bytes = password.encode("utf-8")
    derived = hashlib.pbkdf2_hmac(
        hash_name, password_bytes, salt, iterations, dklen=KEY_LENGTH
    )
    return hmac.compare_digest(derived.hex(), stored_hash)


class PasswordHashingTests(unittest.TestCase):
    def test_safe_equal_matches(self):
        self.assertTrue(safe_equal("hello", "hello"))

    def test_safe_equal_differs(self):
        self.assertFalse(safe_equal("hello", "world"))

    def test_hash_password_is_unique(self):
        h1 = hash_password("hunter2")
        h2 = hash_password("hunter2")
        self.assertNotEqual(h1, h2)

    def test_verify_password_correct(self):
        h = hash_password("s3cr3t!")
        self.assertTrue(verify_password("s3cr3t!", h))

    def test_verify_password_incorrect(self):
        h = hash_password("s3cr3t!")
        self.assertFalse(verify_password("wrong", h))

    def test_verify_password_tampered_hash(self):
        h = hash_password("s3cr3t!")
        self.assertFalse(verify_password("s3cr3t!", h + "00"))

    def test_verify_password_invalid_format(self):
        self.assertFalse(verify_password("password", "not-a-valid-hash"))


if __name__ == "__main__":
